/* Tabla del directorio (DIR-01). Ningún color literal: solo tokens del sistema. */

.tableWrap {
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  background: var(--bw-surface-mist);
  overflow: hidden;
}

.table {
  width: 100%;
  border-collapse: collapse;
}

.th {
  padding: 10px 14px;
  border-bottom: 1px solid var(--bw-line-steel);
  background: var(--bw-surface-mist);
  color: var(--bw-steel-mist);
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-hint);
  font-weight: 700;
  letter-spacing: var(--bw-ls-label);
  text-transform: uppercase;
  text-align: left;
  white-space: nowrap;
  user-select: none;
}

.sortable {
  cursor: pointer;
}

.sortButton {
  padding: 0;
  border: none;
  background: none;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
  cursor: pointer;
}

.sortButton:hover {
  color: var(--bw-ink-steel);
}

/* La flecha de dirección es decoración de CSS, no texto del botón: así el nombre
   accesible de la cabecera ordenable sigue siendo exactamente «Nombre», «País» o
   «Favoritos». */
.sortAsc,
.sortDesc {
  color: var(--bw-calibration-blue);
}

.sortAsc::after {
  content: ' ↑';
}

.sortDesc::after {
  content: ' ↓';
}

.row:hover .td {
  background: var(--bw-hover-surface);
}

.td {
  padding: 11px 14px;
  border-bottom: 1px solid var(--bw-divider-mist);
  color: var(--bw-ink-steel);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  vertical-align: middle;
}

.row:last-child .td {
  border-bottom: none;
}

.nameButton {
  padding: 0;
  border: none;
  background: none;
  color: var(--bw-calibration-blue);
  font-family: inherit;
  font-size: var(--bw-size-input);
  font-weight: 500;
  text-align: left;
  cursor: pointer;
}

.nameButton:disabled {
  cursor: default;
}

.countryBadge {
  display: inline-block;
  padding: 2px 7px;
  border: 1px solid var(--bw-badge-neutral-border-soft);
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  white-space: nowrap;
}

.contact {
  color: var(--bw-steel-mist);
  font-size: var(--bw-size-label);
  white-space: nowrap;
}

.favorite {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--bw-brass);
  font-size: var(--bw-size-label);
  font-weight: 500;
}

.emptyCell {
  padding: 28px 14px;
  color: var(--bw-steel-mist);
  font-size: var(--bw-size-input);
  text-align: center;
}

import type {
  DirectoryRow,
  DirectorySort,
  DirectorySortField,
} from '../../lib/directory';
import styles from './DirectoryTable.module.css';

interface Props {
  rows: DirectoryRow[];
  sort: DirectorySort;
  onSort: (field: DirectorySortField) => void;
  onOpenOrganization: (id: string) => void;
}

interface Column {
  label: string;
  /** Ausente = la columna no es reordenable (Teléfono y Email, spec §3). */
  sortField?: DirectorySortField;
}

/**
 * Las CINCO columnas de la spec §3, en orden fijo e inamovible. Se ordenan filas,
 * nunca columnas. Nombre, País y Favoritos son reordenables; Teléfono y Email no,
 * y no es un olvido: ordenar un directorio por número de teléfono no significa
 * nada.
 */
const COLUMNS: readonly Column[] = [
  { label: 'Nombre', sortField: 'name' },
  { label: 'País', sortField: 'country' },
  { label: 'Teléfono' },
  { label: 'Email' },
  { label: 'Favoritos', sortField: 'favorite_count' },
];

/**
 * Tabla del directorio.
 *
 * Presentacional: pinta las filas EN EL ORDEN QUE LAS RECIBE y no llama a la red
 * —ordenar y paginar es cosa de `Directory`—. El estado vacío vive aquí dentro,
 * porque «no hay filas» es un estado de la lista y no de la pantalla: sigue
 * siendo una `<table>` de verdad y el hueco va en una fila con `colSpan`.
 */
export function DirectoryTable({ rows, sort, onSort, onOpenOrganization }: Props) {
  return (
    <div className={styles.tableWrap}>
      <table className={styles.table}>
        <thead>
          <tr>
            {COLUMNS.map((column) => {
              const field = column.sortField;
              const active = field !== undefined && sort.field === field;

              const cellClass = [styles.th];
              if (field !== undefined) {
                cellClass.push(styles.sortable);
                if (active) cellClass.push(sort.ascending ? styles.sortAsc : styles.sortDesc);
              }

              // `aria-sort` va en el `<th>` y SOLO en la columna activa: las
              // otras no llevan el atributo en absoluto, ni siquiera 'none'.
              const ariaSort = active
                ? sort.ascending
                  ? 'ascending'
                  : 'descending'
                : undefined;

              return (
                <th
                  key={column.label}
                  scope="col"
                  className={cellClass.join(' ')}
                  aria-sort={ariaSort}
                >
                  {field !== undefined ? (
                    // La cabecera ordenable es un BOTÓN dentro del `<th>`: con el
                    // manejador en la celda, ordenar no existiría con teclado.
                    // La dirección no viaja nunca desde aquí — la decide
                    // `nextSort` en `Directory`.
                    <button type="button" className={styles.sortButton} onClick={() => onSort(field)}>
                      {column.label}
                    </button>
                  ) : (
                    column.label
                  )}
                </th>
              );
            })}
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td colSpan={5} className={styles.emptyCell}>
                No hemos encontrado organizaciones que coincidan con los filtros aplicados.
              </td>
            </tr>
          ) : (
            rows.map((row) => (
              <tr key={row.id} className={styles.row}>
                <td className={styles.td}>
                  {/*
                   * DIR-02 (la ficha pública de la organización) no está
                   * construida todavía. El nombre se pinta como control apagado
                   * y con el motivo a la vista: un enlace que no lleva a ninguna
                   * parte, delante de alguien que no conoce la aplicación, parece
                   * una aplicación rota. `onOpenOrganization(row.id)` se conserva
                   * en el `onClick` —un botón deshabilitado no lo dispara— porque
                   * es el contrato del componente para cuando exista DIR-02,
                   * mismo patrón que `Consultar`/`Contactar` en SRCH-01.
                   */}
                  <button
                    type="button"
                    className={styles.nameButton}
                    disabled
                    title="La ficha de organización (DIR-02) llega en una próxima versión."
                    onClick={() => onOpenOrganization(row.id)}
                  >
                    {row.name}
                  </button>
                </td>
                <td className={styles.td}>
                  {/* El CÓDIGO ISO tal cual: aquí no va `row.countryLabel`, que es
                      la etiqueta larga y solo sirve para el desplegable de filtro. */}
                  <span className={styles.countryBadge}>{row.country}</span>
                </td>
                <td className={styles.td}>
                  <span className={styles.contact}>{row.phone === '' ? '—' : row.phone}</span>
                </td>
                <td className={styles.td}>
                  <span className={styles.contact}>{row.email === '' ? '—' : row.email}</span>
                </td>
                <td className={styles.td}>
                  <span className={styles.favorite}>
                    <span aria-hidden="true">★</span> {row.favoriteCount}
                  </span>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}
